static void saveBooksToFile(List<Book> books, Path path) throws IOException {
    try (FileWriter w = new FileWriter(path.toFile())) {
        new Gson().toJson(books, w);
    }
}

static List<Book> loadBooksFromFile(Path path) throws IOException {
    Type listType = new TypeToken<List<Book>>() {}.getType();
    try (FileReader r = new FileReader(path.toFile())) {
        return new Gson().fromJson(r, listType);
    }
}

