static class JsonMapDb {
    private final Map<String, Book> dane = new HashMap<>();
    private final Path plik;
    JsonMapDb(Path plik) { this.plik = plik; }

    void insert(String id, Book book) throws IOException { dane.put(id, book); zapisz(); }
    Book findById(String id) { return dane.get(id); }
    void deleteById(String id) throws IOException { dane.remove(id); zapisz(); }

    private void zapisz() throws IOException {
        try (FileWriter w = new FileWriter(plik.toFile())) {
            new Gson().toJson(dane, w);
        }
    }
}

static class User implements Serializable {
    static final long serialVersionUID = 1L;
    String username;
    transient String password;
    User(String u, String p) { username = u; password = p; }
}

User u = new User("admin", "tajne123");
String gsonJson = new Gson().toJson(u);
System.out.println(gsonJson.contains("tajne123")); // false - Gson TEZ respektuje transient!
// Wniosek: Gson domyslnie pomija pola transient, tak samo jak natywna serializacja Javy

