static void mergeJsonFiles(Path file1, Path file2, Path outputFile) throws IOException {
    List<Book> lista1 = loadBooksFromFile(file1);
    List<Book> lista2 = loadBooksFromFile(file2);

    Map<String, Book> unikalne = new LinkedHashMap<>();
    for (Book b : lista1) unikalne.put(b.title(), b);
    for (Book b : lista2) unikalne.put(b.title(), b);

    saveBooksToFile(new ArrayList<>(unikalne.values()), outputFile);
}

